    private void DrawRiffTab(PracticeRiff riff)
    {var capturedDocument = documentContext.Current;
        if(riffTab is null)return;riffTab.Children.Clear();riffTab.ColumnDefinitions.Clear();riffTab.RowDefinitions.Clear();riffTabCells.Clear();var starts=riff.Notes.Select(n=>n.Start).Distinct().Order().ToArray();for(int col=0;col<=starts.Length;++col)riffTab.ColumnDefinitions.Add(new(){Width=new(col==0?60:64)});for(int row=0;row<7;++row)riffTab.RowDefinitions.Add(new(){Height=new(40)});var tuning=LibraryPractice.RiffTuning(catalog!,riff);
        for(int str=0;str<6;++str){var label=Text(NoteLabel(tuning[str]),true);Grid.SetRow(label,6-str);riffTab.Children.Add(label);}
        for(int i=0;i<starts.Length;++i){int col=i+1;var label=Text(starts[i].ToString("0.##"),true);Grid.SetColumn(label,col);riffTab.Children.Add(label);for(int str=0;str<6;++str){var note=riff.Notes.FirstOrDefault(n=>n.Start==starts[i] && n.StringIndex==str);var cell=new Button{Content=note is null?"—":note.Fret.ToString(),IsEnabled=note is not null,HorizontalAlignment=HorizontalAlignment.Stretch,Margin=new(2)};Grid.SetRow(cell,6-str);Grid.SetColumn(cell,col);riffTab.Children.Add(cell);if(note is not null){Microsoft.UI.Xaml.Automation.AutomationProperties.SetName(cell,$"Doba {note.Start:0.##}, struna {6-note.StringIndex}, pražec {note.Fret}, {LibraryPractice.Technique(note.Technique)}");riffTabCells.Add((cell,note.Start,note.Duration));cell.Click+=(_,_)=>{using var documentScope = documentContext.Enter(capturedDocument);if(!capturedDocument.IsAlive)return;if(riffNotesList is not null)riffNotesList.SelectedIndex=riff.Notes.OrderBy(n=>n.Start).ToList().IndexOf(note);};}}}
    }
    private void RefreshRiff(RhythmSnapshot value)
    {
        if(selectedRiff is null || CurrentTarget.ViewId!="19")return;double position=value.ElapsedBeats%LibraryPractice.RiffBeats(selectedRiff);foreach(var entry in riffTabCells)entry.Cell.Style=position>=entry.Start && position<entry.Start+entry.Duration?(Style)Application.Current.Resources["VintageRootButtonStyle"]:null;
    }
